package("expo-image-picker")
    set_kind("library", {headeronly = true})
    set_homepage("https://github.com/expo/expo/tree/main/packages/expo-image-picker")
    set_description("expo-image-picker 57.0.20, the Expo SDK picker of photos and videos, from its npm tarball: the iOS module sources the host builds from, patched so iOS 6 uses UIImagePickerController with the UTI constants, rejects multiple selection there, and gates PhotoKit, PHPickerController and live photo code to iOS 14+, the asset metadata to iOS 11+, and the library permission to the assets library on iOS 6 and 7")
    set_license("MIT")
    set_policy("package.strict_compatibility", true)

    add_urls("https://registry.npmjs.org/expo-image-picker/-/expo-image-picker-$(version).tgz")
    add_versions("57.0.20", "98249e2e89f8ad15c9ca427dc76ba018e5dcd8677d78ff230f7a8780f1d48b29")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepicker-exceptions-ios6.patch"), "4919efd3c0970dcdc086528a0d66883eae5de3d4b68ffa447e6739e053736a29")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickerhandler-ios6.patch"), "08aab8fffc7b66866031f419a15b655403c82f458617a1b516475b1129c50f83")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickermodule-ios6.patch"), "59828dcff5188cc2caddf1b5d89b91d72db1a38ab61126e67b0481bfbb94f8d0")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickeroptions-ios6.patch"), "c30258429a3cc3f651e4e1587d976d51092334803dbb88f3da33a81a06283ca1")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickermediahandler-ios6.patch"), "cc161ab384713d9b952c83ee37bf39c6c93bd4becd700f17fc66a8c23dd08d5d")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickerutils-ios6.patch"), "b170bc839bcb4ba1993af13f02589831c67eeb045e7885aa7fd622443099d56a")
    add_patches("57.0.20", path.join(os.scriptdir(), "patches", "imagepickerpermissions-ios6.patch"), "1a17a250b02b34a4dc5e0a70bf16c442dac3536dbec70217aaca20c1e0e94d90")

    on_install(function (package)
        os.cp("*", package:installdir() .. "/")
    end)

    on_test(function (package)
        local json = import("core.base.json")
        local manifest = json.decode(io.readfile(path.join(package:installdir(), "package.json")))
        assert(manifest.name == "expo-image-picker" and manifest.version == "57.0.20", "the package is " .. manifest.name .. " " .. manifest.version)
        assert(os.isfile(path.join(package:installdir(), "ios", "ImagePickerModule.swift")), "expo-image-picker has no iOS module")
        assert(os.isfile(path.join(package:installdir(), "expo-module.config.json")), "expo-image-picker has no expo-module.config.json")
        assert(io.readfile(path.join(package:installdir(), "ios", "ImagePickerModule.swift")):find("#available", 1, true), "ImagePickerModule is not guarded for iOS 14+")
        assert(io.readfile(path.join(package:installdir(), "ios", "ImagePickerHandler.swift")):find("@available", 1, true), "ImagePickerHandler is not guarded for iOS 14+")
        assert(io.readfile(path.join(package:installdir(), "ios", "ImagePickerExceptions.swift")):find("ImagePickerMissingCurrentViewControllerException", 1, true), "the picker exception is not renamed away from expo-sharing's")
        assert(io.readfile(path.join(package:installdir(), "ios", "ImagePickerPermissionRequesters.swift")):find("ALAssetsLibrary", 1, true), "the library permission has no iOS 6 path")
    end)
